// Detect EDR source and parse accordingly
const webhook = $input.first().json;
const body = webhook.body || webhook;

let normalizedAlert = {};

// Detect SentinelOne (has threatInfo)
if (body.threatInfo || (body.data && body.data.threatInfo)) {
  const threat = body.threatInfo || body.data?.threatInfo || body;
  const agent = body.agentRealtimeInfo || body.agentDetectionInfo || body.data?.agentRealtimeInfo || {};

  normalizedAlert = {
    source: 'sentinelone',
    source_alert_id: threat.threatId || threat.id || '',
    timestamp: threat.createdAt || threat.identifiedAt || new Date().toISOString(),
    severity: mapS1Severity(threat.confidenceLevel, threat.severity),
    confidence: threat.confidenceLevel || 'medium',
    hostname: agent.agentComputerName || agent.computerName || '',
    endpoint_ip: agent.agentIpAddress || agent.externalIp || '',
    endpoint_os: agent.agentOsType || agent.osType || '',
    endpoint_user: agent.loggedInUserName || threat.username || '',
    site_name: agent.siteName || '',
    site_id: agent.siteId || '',
    account_name: agent.accountName || '',
    threat_name: threat.threatName || threat.classification || '',
    threat_classification: threat.classification || threat.classificationSource || '',
    threat_description: threat.description || '',
    mitre_tactics: threat.mitreTactics || [],
    mitre_techniques: threat.mitreTechniques || [],
    file_path: threat.filePath || '',
    file_hash_sha256: threat.sha256 || threat.fileContentHash || '',
    file_hash_sha1: threat.sha1 || '',
    file_hash_md5: threat.md5 || '',
    file_size: threat.fileSize || null,
    file_signed: threat.signedStatus === 'signed',
    process_name: threat.processName || threat.originator || '',
    process_id: threat.pid || null,
    command_line: threat.commandLineArguments || threat.originatorProcess || '',
    parent_process_name: threat.parentProcessName || '',
    parent_command_line: threat.parentProcessCommandLine || '',
    remote_ip: threat.networkInfo?.remoteIp || '',
    remote_domain: threat.networkInfo?.remoteDomain || '',
    remote_port: threat.networkInfo?.remotePort || null,
    remote_url: threat.networkInfo?.url || '',
    raw_payload: body
  };
}
// Detect CrowdStrike (has metadata or event structure)
else if (body.metadata || body.event || body.detection_id) {
  const detection = body.event || body.detection || body;
  const metadata = body.metadata || {};
  const device = detection.device || detection.host || {};

  normalizedAlert = {
    source: 'crowdstrike',
    source_alert_id: detection.detection_id || detection.composite_id || metadata.eventId || '',
    timestamp: detection.created_timestamp || detection.timestamp || new Date().toISOString(),
    severity: mapCSSeverity(detection.severity, detection.max_severity_displayname),
    confidence: String(detection.confidence || 'medium'),
    hostname: device.hostname || device.device_id || '',
    endpoint_ip: device.local_ip || device.external_ip || '',
    endpoint_os: device.os_version || device.platform_name || '',
    endpoint_user: detection.user_name || device.machine_user || '',
    site_name: device.site_name || (device.groups ? device.groups[0] : '') || '',
    site_id: device.device_id || '',
    account_name: metadata.customerIDString || '',
    threat_name: detection.detect_name || detection.tactic || '',
    threat_classification: detection.technique || '',
    threat_description: detection.detect_description || detection.description || '',
    mitre_tactics: extractCSTactics(detection),
    mitre_techniques: extractCSTechniques(detection),
    file_path: detection.filepath || detection.filename || '',
    file_hash_sha256: detection.sha256 || detection.ioc_value || '',
    file_hash_sha1: detection.sha1 || '',
    file_hash_md5: detection.md5 || '',
    file_size: detection.file_size || null,
    file_signed: detection.file_signed || false,
    process_name: detection.process_name || detection.filename || '',
    process_id: detection.process_id || detection.local_process_id || null,
    command_line: detection.cmdline || detection.command_line || '',
    parent_process_name: detection.parent_process_name || '',
    parent_command_line: detection.parent_cmdline || detection.parent_command_line || '',
    remote_ip: detection.remote_address || '',
    remote_domain: detection.domain || '',
    remote_port: detection.remote_port || null,
    remote_url: detection.url || '',
    raw_payload: body
  };
} else {
  // Unknown format - pass through what we have
  normalizedAlert = {
    source: 'unknown',
    source_alert_id: '',
    timestamp: new Date().toISOString(),
    severity: 'medium',
    hostname: '',
    threat_name: 'Unknown Alert',
    raw_payload: body
  };
}

function mapS1Severity(confidence, severity) {
  const map = { 'malicious': 'critical', 'suspicious': 'high', 'n/a': 'medium' };
  if (severity && map[severity.toLowerCase()]) return map[severity.toLowerCase()];
  if (confidence && map[confidence.toLowerCase()]) return map[confidence.toLowerCase()];
  return 'medium';
}

function mapCSSeverity(num, name) {
  if (name) {
    const map = { 'critical': 'critical', 'high': 'high', 'medium': 'medium', 'low': 'low', 'informational': 'info' };
    return map[name.toLowerCase()] || 'medium';
  }
  if (typeof num === 'number') {
    if (num >= 80) return 'critical';
    if (num >= 60) return 'high';
    if (num >= 40) return 'medium';
    if (num >= 20) return 'low';
    return 'info';
  }
  return 'medium';
}

function extractCSTactics(d) {
  const t = [];
  if (d.tactic) t.push(d.tactic);
  if (d.tactics) t.push(...d.tactics);
  if (d.behaviors) d.behaviors.forEach(b => { if (b.tactic) t.push(b.tactic); });
  return [...new Set(t)];
}

function extractCSTechniques(d) {
  const t = [];
  if (d.technique) t.push(d.technique);
  if (d.technique_id) t.push(d.technique_id);
  if (d.behaviors) d.behaviors.forEach(b => { if (b.technique) t.push(b.technique); if (b.technique_id) t.push(b.technique_id); });
  return [...new Set(t)];
}

return [{ json: normalizedAlert }];

// Extract IOCs from the normalized alert
const alert = $input.first().json;

const iocs = {
  hashes: [],
  ips: [],
  domains: [],
  urls: []
};

// Collect file hashes
if (alert.file_hash_sha256) iocs.hashes.push({ type: 'sha256', value: alert.file_hash_sha256 });
if (alert.file_hash_sha1) iocs.hashes.push({ type: 'sha1', value: alert.file_hash_sha1 });
if (alert.file_hash_md5) iocs.hashes.push({ type: 'md5', value: alert.file_hash_md5 });

// Collect IPs (filter out private IPs)
const privateIpRegex = /^(10\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|127\.|0\.)/;
if (alert.remote_ip && !privateIpRegex.test(alert.remote_ip)) {
  iocs.ips.push(alert.remote_ip);
}

// Collect domains
if (alert.remote_domain) {
  iocs.domains.push(alert.remote_domain);
}

// Collect URLs
if (alert.remote_url) {
  iocs.urls.push(alert.remote_url);
}

return [{ 
  json: {
    alert: alert,
    iocs: iocs,
    primary_hash: alert.file_hash_sha256 || alert.file_hash_sha1 || alert.file_hash_md5 || '',
    primary_ip: iocs.ips[0] || '',
    primary_domain: iocs.domains[0] || ''
  }
}];

// Aggregate enrichment results from all threat intel sources
const items = $input.all();

// Find the original alert data (look for the one with 'alert' property)
let alertData = null;
for (const item of items) {
  if (item.json && item.json.alert) {
    alertData = item.json;
    break;
  }
}

// If not found, use first item
if (!alertData) {
  alertData = { alert: items[0]?.json || {}, iocs: {} };
}

const alertInfo = alertData.alert || {};

const enrichment = {
  virustotal: { hash: null, ip: null },
  alienvault: { hash: null, ip: null },
  summary: {
    is_malicious: false,
    highest_threat_score: 0,
    detection_count: 0,
    total_engines: 0,
    threat_names: [],
    malware_families: [],
    tags: []
  }
};

// Process all items for enrichment data
for (const item of items) {
  const d = item.json;
  if (!d) continue;

  // VirusTotal response (has data.attributes.last_analysis_stats)
  if (d.data && d.data.attributes && d.data.attributes.last_analysis_stats) {
    const stats = d.data.attributes.last_analysis_stats;
    const total = (stats.malicious || 0) + (stats.suspicious || 0) + (stats.harmless || 0) + (stats.undetected || 0);

    if (d.data.attributes.sha256 || d.data.type === 'file') {
      enrichment.virustotal.hash = {
        found: true,
        malicious: stats.malicious || 0,
        suspicious: stats.suspicious || 0,
        total: total,
        file_type: d.data.attributes.type_description || '',
        tags: d.data.attributes.tags || []
      };
      enrichment.summary.detection_count += stats.malicious || 0;
      enrichment.summary.total_engines += total;
      if (stats.malicious > 0) enrichment.summary.is_malicious = true;
      if (d.data.attributes.tags) enrichment.summary.tags.push(...d.data.attributes.tags);
    } else {
      enrichment.virustotal.ip = {
        found: true,
        malicious: stats.malicious || 0,
        country: d.data.attributes.country || '',
        as_owner: d.data.attributes.as_owner || ''
      };
      if (stats.malicious > 0) enrichment.summary.is_malicious = true;
    }
  }

  // AlienVault response (has pulse_info)
  if (d.pulse_info) {
    const pulseCount = d.pulse_info.count || 0;
    const avResult = {
      found: true,
      pulse_count: pulseCount,
      pulses: (d.pulse_info.pulses || []).slice(0, 5).map(p => ({ name: p.name, tags: p.tags }))
    };

    if (d.type === 'file' || d.file_type) {
      enrichment.alienvault.hash = avResult;
    } else {
      enrichment.alienvault.ip = avResult;
    }

    if (pulseCount > 0) {
      enrichment.summary.is_malicious = true;
    }
  }
}

// Calculate threat score
let threatScore = 0;
if (enrichment.virustotal.hash && enrichment.virustotal.hash.malicious && enrichment.virustotal.hash.total) {
  threatScore = Math.min(100, (enrichment.virustotal.hash.malicious / enrichment.virustotal.hash.total) * 100);
}
if (enrichment.alienvault.hash && enrichment.alienvault.hash.pulse_count > 0) {
  threatScore = Math.max(threatScore, Math.min(100, enrichment.alienvault.hash.pulse_count * 10));
}
enrichment.summary.highest_threat_score = Math.round(threatScore);
enrichment.summary.tags = [...new Set(enrichment.summary.tags)];

// Build chatInput for AI Agent node
const chatInput = `You are an expert security analyst. Analyze this security alert and provide actionable recommendations.

Respond in JSON format with these fields:
- summary (1-2 sentences)
- severity_assessment (critical/high/medium/low)
- threat_type
- is_likely_false_positive (boolean)
- immediate_actions (array)
- recommended_actions (array)
- investigation_steps (array)
- potential_impact

## Alert Details
- **Source:** ${alertInfo.source || 'Unknown'}
- **Severity:** ${alertInfo.severity || 'Unknown'}
- **Hostname:** ${alertInfo.hostname || 'Unknown'}
- **User:** ${alertInfo.endpoint_user || 'Unknown'}
- **Threat Name:** ${alertInfo.threat_name || 'Unknown'}
- **Classification:** ${alertInfo.threat_classification || 'Unknown'}
- **Process:** ${alertInfo.process_name || 'Unknown'}
- **Command Line:** ${alertInfo.command_line || 'N/A'}
- **File Path:** ${alertInfo.file_path || 'N/A'}
- **SHA256:** ${alertInfo.file_hash_sha256 || 'N/A'}
- **Remote IP:** ${alertInfo.remote_ip || 'N/A'}
- **Remote Domain:** ${alertInfo.remote_domain || 'N/A'}

## Threat Intelligence Summary
- **Malicious:** ${enrichment.summary.is_malicious}
- **Threat Score:** ${enrichment.summary.highest_threat_score}/100
- **Detections:** ${enrichment.summary.detection_count}/${enrichment.summary.total_engines} engines
- **Tags:** ${enrichment.summary.tags.join(', ') || 'None'}

Provide your analysis as JSON.`;

return [{
  json: {
    alert: alertInfo,
    iocs: alertData.iocs,
    enrichment: enrichment,
    chatInput: chatInput
  }
}];

// Parse Claude's response and preserve enriched alert data
const claudeResponse = $input.first().json;

// Get the enriched data from the previous Merge Enrichment node
const enrichedNode = $('Merge Enrichment').first();
const enrichedData = enrichedNode ? enrichedNode.json : {};

let aiAnalysis = {
  summary: 'AI analysis unavailable',
  severity_assessment: 'medium',
  immediate_actions: ['Review alert manually'],
  recommended_actions: ['Investigate endpoint activity']
};

try {
  if (claudeResponse.content && claudeResponse.content[0] && claudeResponse.content[0].text) {
    let responseText = claudeResponse.content[0].text;

    // Extract JSON from markdown code blocks if present
    const jsonMatch = responseText.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (jsonMatch) {
      responseText = jsonMatch[1];
    }

    aiAnalysis = JSON.parse(responseText.trim());
  }
} catch (e) {
  aiAnalysis.error = e.message;
}

return [{
  json: {
    alert: enrichedData.alert || {},
    enrichment: enrichedData.enrichment || { summary: {} },
    ai_analysis: aiAnalysis
  }
}];

