parameters.jsCode:
// Prepare data for Teams notification
const ticketResponse = $input.first().json;

// Get alert and analysis from Parse AI Response node
const prevNode = $('Parse AI Response').first();
const prevData = prevNode ? prevNode.json : {};
const alert = prevData.alert || {};
const enrichment = prevData.enrichment || { summary: {} };
const aiAnalysis = prevData.ai_analysis || {};

// Extract ticket info
let ticketUrl = '';
let ticketNumber = '';
if (ticketResponse.data && ticketResponse.data.createTicket) {
  const ticket = ticketResponse.data.createTicket;
  ticketNumber = ticket.ticketNumber || ticket.id;
  ticketUrl = 'https://app.superops.ai/tickets/' + ticket.id;
}

// Severity emoji
const severityEmoji = {
  critical: '🔴',
  high: '🟠', 
  medium: '🟡',
  low: '🟢',
  info: 'ℹ️'
};

const severity = (alert.severity || 'medium').toLowerCase();
const emoji = severityEmoji[severity] || '⚠️';

const messageTitle = emoji + ' Security Alert: ' + (alert.threat_name || 'Unknown Threat');
const messageBody = '**Hostname:** ' + (alert.hostname || 'N/A') + '\n' +
  '**User:** ' + (alert.endpoint_user || 'N/A') + '\n' +
  '**Severity:** ' + (alert.severity || 'medium').toUpperCase() + '\n' +
  '**Classification:** ' + (alert.threat_classification || 'N/A') + '\n\n' +
  '**AI Summary:** ' + (aiAnalysis.summary || 'Analysis unavailable') + '\n\n' +
  '**Threat Score:** ' + (enrichment.summary.highest_threat_score || 0) + '/100\n' +
  '**Detections:** ' + (enrichment.summary.detection_count || 0) + '/' + (enrichment.summary.total_engines || 0) + ' engines\n\n' +
  '🎫 **Ticket:** ' + (ticketUrl || 'Not created');

return [{
  json: {
    alert: alert,
    enrichment: enrichment,
    ai_analysis: aiAnalysis,
    ticket_url: ticketUrl,
    ticket_number: ticketNumber,
    severity_emoji: emoji,
    message_title: messageTitle,
    message_body: messageBody
  }
}];
